arguments.command:
# Check the debuglink name and use dynamic symbols to resolve addresses
aarch64-linux-gnu-readelf -p .gnu_debuglink /tmp/symbols/libmonosgen-2.0.so 2>/dev/null
echo "==="
# Use objdump or nm with dynamic symbols to find function at each address
for addr in 0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04; do
  echo -n "$addr: "
  aarch64-linux-gnu-nm -D /tmp/symbols/libmonosgen-2.0.so 2>/dev/null | awk -v a="$addr" '
    BEGIN { addr = strtonum(a); best=""; best_off=99999999 }
    /^[0-9a-f]+ [TtWw]/ { 
      sym_addr = strtonum("0x"$1); 
      if (sym_addr <= addr && (addr - sym_addr) < best_off) { 
        best = $3; best_off = addr - sym_addr; best_addr = sym_addr
      } 
    }
    END { if (best != "") printf "%s+0x%x\n", best, best_off; else print "??" }
  '
done

